import React from 'react';
import { registerLivePlayEvent } from './firebase';

const PlayerContext = React.createContext({
  state: { playing: false, src: '', title: '', cover: '', artistId: '' },
  play: async (_opts) => {},
  pause: () => {},
});

export function PlayerProvider({ children }) {
  const audioRef = React.useRef(null);
  const [state, setState] = React.useState({ playing: false, src: '', title: '', cover: '', artistId: '' });
  const lastPulseRef = React.useRef(0);

  React.useEffect(() => {
    if (!audioRef.current) {
      const a = new Audio();
      a.preload = 'auto';
      a.crossOrigin = 'anonymous';
      try { a.setAttribute('playsinline', ''); } catch {}
      try { a.style.display = 'none'; document.body.appendChild(a); } catch {}
      audioRef.current = a;
      const onPlay = () => setState(s => ({ ...s, playing: true }));
      const onPause = () => setState(s => ({ ...s, playing: false }));
      const onEnded = () => setState(s => ({ ...s, playing: false }));
      const onError = (ev) => {
        const err = a.error;
        if (err) {
          console.warn('[PlayerContext] media error', err.code, err.message || err);
        } else {
          console.warn('[PlayerContext] generic audio error', ev?.type);
        }
      };
      a.addEventListener('play', onPlay);
      a.addEventListener('pause', onPause);
      a.addEventListener('ended', onEnded);
      a.addEventListener('error', onError);
    }
  }, []);

  // Sanitizza URL Storage: corregge bucket errato e forza https
  function normalizeStorageUrl(u) {
    try {
      if (!u || typeof u !== 'string') return u;
      let s = u.trim();
      // sostituisci eventuale bucket errato
      s = s.replace(
        /([?&]alt=media\b.*$)|$/,
        (m) => m // no-op per mantenere la query
      ).replace(
        /\b(b=)arteregistrazioni-2025\.firebasestorage\.app\b/,
        '$1arteregistrazioni-2025.appspot.com'
      );
      // correzione alternativa per URL con path bucket
      s = s.replace(
        /\/v0\/b\/arteregistrazioni-2025\.firebasestorage\.app\//,
        '/v0/b/arteregistrazioni-2025.appspot.com/'
      );
      if (s.startsWith('http://')) s = 'https://' + s.slice(7);
      return s;
    } catch { return u; }
  }

  // Fa una HEAD per verificare esistenza e content-type prima di impostare src (evita errori 404/format)
  async function preflightAudio(url) {
    try {
      const resp = await fetch(url, { method: 'HEAD' });
      if (!resp.ok) return { ok: false, status: resp.status };
      const ct = resp.headers.get('Content-Type') || '';
      if (!/audio|octet-stream/i.test(ct)) {
        return { ok: false, status: resp.status, ct };
      }
      return { ok: true, status: resp.status, ct };
    } catch (e) {
      return { ok: false, error: e?.message || String(e) };
    }
  }

  const play = React.useCallback(async ({ src, title, cover, artistId }) => {
    if (!src) { console.warn('[PlayerContext.play] src vuoto, abort'); return; }
    src = normalizeStorageUrl(src);
    const a = audioRef.current;
    if (!a) { console.error('[PlayerContext.play] audio element mancante'); return; }
    // Preflight prima di cambiare la sorgente
    const check = await preflightAudio(src);
    if (!check.ok) {
      console.warn('[PlayerContext.play] preflight fallito', check);
      return;
    }
    try {
      const changingSource = a.src !== src;
      if (changingSource) {
        try { a.pause(); } catch {}
        a.src = '';
        a.removeAttribute('src');
        a.load(); // forza reset
        a.src = src;
      }
      a.muted = false;
      a.volume = 1;
      console.log('[PlayerContext.play] attempt play', { src, title, cover, artistId, changingSource });
      try {
        await a.play();
      } catch (e1) {
        console.warn('[PlayerContext.play] primo tentativo fallito, provo sblocco autoplay', e1?.name, e1?.message);
        const SILENT_WAV = 'data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAIlYAABAAAAACAAACaGwAAAAA';
        try { a.src = SILENT_WAV; await a.play(); } catch (e2) { console.warn('[PlayerContext.play] silent wav fail', e2?.name, e2?.message); }
        // ripristina traccia
        a.src = src;
        try { await a.play(); } catch (e3) {
          console.error('[PlayerContext.play] secondo tentativo fallito', e3?.name, e3?.message);
          return;
        }
      }
      setState({ playing: true, src, title: title || '', cover: cover || '', artistId: artistId || '' });
      const now = Date.now();
      if (now - (lastPulseRef.current || 0) > 8000) {
        lastPulseRef.current = now;
        registerLivePlayEvent({ artistId: artistId || '', city: 'Roma', country: 'Italia' }).catch(err => {
          console.warn('[PlayerContext.play] pulse error', err?.message || err);
        });
      }
      console.log('[PlayerContext.play] PLAY OK');
    } catch (e) {
      console.error('[PlayerContext.play] errore generale', e?.name, e?.message);
    }
  }, []);

  const pause = React.useCallback(() => {
    const a = audioRef.current;
    if (!a) return;
    try { a.pause(); } catch {}
    // Svuota stato per far scomparire il mini player
    setState({ playing: false, src: '', title: '', cover: '', artistId: '' });
  }, []);

  const value = React.useMemo(() => ({ state, play, pause }), [state, play, pause]);
  return (
    <PlayerContext.Provider value={value}>
      {children}
    </PlayerContext.Provider>
  );
}

export function usePlayer() {
  return React.useContext(PlayerContext);
}
